      "interpretation": "Preço consolidando em torno da MM200; sem direção definida."
    },
    {
      "indicator": "MM20",
      "reading": "≈ R$37–37,5 (visual)",
      "interpretation": "MM20 levemente descendente e próxima ao preço — curto prazo fraco."
    },
    {
      "indicator": "MM50",
      "reading": "≈ R$39,0 (visual)",
      "interpretation": "MM50 acima do preço, atuando como resistência de médio prazo."
    },
    {
      "indicator": "MM200",
      "reading": "≈ R$37,0–37,5 (visual)",
      "interpretation": "MM200 praticamente plana — tendência de longo prazo neutra."
    },
    {
      "indicator": "EMA9",
      "reading": "≈ R$37,0 (visual)",
      "interpretation": "EMA9 ligeiramente abaixo da EMA21 — curto prazo com leve pressão vendedora."
    },
    {
      "indicator": "EMA21",
      "reading": "≈ R$37,2–37,5 (visual)",
      "interpretation": "EMA21 convergente com outras médias — indecisão."
    },
    {
      "indicator": "MACD",
      "reading": "MACD ≈ 0; histograma levemente negativo (visual)",
      "interpretation": "Momentum neutro a levemente negativo; cruzamento recente indica perda de força."
    },
    {
      "indicator": "Bollinger (20, 2σ)",
